  "workerFlowStep3Desc": "ਗਾਹਕ ਦੇ ਘਰ ਪਹੁੰਚ ਕੇ, ਉਹਨਾਂ ਤੋਂ 4-ਅੰਕਾਂ ਦਾ ਕੋਡ ਪੁੱਛੋ ਅਤੇ ਕੰਮ ਸ਼ੁਰੂ ਕਰੋ।",
  "workerFlowStep3Title": "ਕੰਮ ਸ਼ੁਰੂ ਕਰਨ ਵਾਲਾ OTP ਦਰਜ ਕਰੋ:",
  "workerFlowStep4Desc": "ਕੰਮ ਖਤਮ ਹੋਣ 'ਤੇ \"ਪੂਰਾ ਹੋਇਆ\" ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਕਰੋ। ਜ਼ੀਰੋ ਕਮਿਸ਼ਨ ਨਾਲ ਪੂਰੀ ਕਮਾਈ ਤੁਰੰਤ ਖਾਤੇ ਵਿੱਚ ਜਮ੍ਹਾਂ ਹੋ ਜਾਵੇਗੀ।",
  "workerFlowStep4Title": "ਕੰਮ ਪੂਰਾ ਕਰੋ ਅਤੇ ਤੁਰੰਤ ਭੁਗਤਾਨ ਪ੍ਰਾਪਤ ਕਰੋ:",
  "workerFlowStep5Desc": "ਉੱਚ ਰੇਟਿੰਗ ਬਣਾਈ ਰੱਖੋ, ਅਕੈਡਮੀ ਦੇ ਪਾਠ ਪੂਰੇ ਕਰੋ, ਅਤੇ ਉੱਚ ਤਨਖਾਹ ਵਾਲੇ ਕੰਮ ਪ੍ਰਾਪਤ ਕਰੋ।",
  "workerFlowStep5Title": "ਹੁਨਰ ਸੁਧਾਰੋ ਅਤੇ ਵੱਧ ਕਮਾਈ ਕਰੋ:",
  "workerHowItWorksDesc": "ਸਹਿਕਾਰ ਕਨੈਕਟ ਵਰਕਰ ਪੋਰਟਲ ਤੁਹਾਨੂੰ ਬਿਨਾਂ ਕਿਸੇ ਵਿਚੋਲੇ ਦੇ ਸਿੱਧੇ ਨੇੜਲੇ ਗਾਹਕਾਂ ਨਾਲ ਜੋੜਦਾ ਹੈ। ਤੁਸੀਂ ਕੰਮ ਦੀਆਂ ਬੇਨਤੀਆਂ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦੇ ਹੋ, ਸੁਰੱਖਿਅਤ OTP ਨਾਲ ਕੰਮ ਸ਼ੁਰੂ ਕਰ ਸਕਦੇ ਹੋ, ਤੁਰੰਤ ਮਿਹਨਤਾਨਾ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਸਮਾਜਿਕ ਸੁਰੱਖਿਆ ਲਾਭ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦੇ ਹੋ।",
  "workerIdHeader": "ਵਰਕਰ ਆਈਡੀ",
  "workerMandatory1Desc": "ਗਾਹਕ ਵੱਲੋਂ 4-ਅੰਕਾਂ ਦਾ ਕੰਮ ਸ਼ੁਰੂਆਤੀ OTP ਪ੍ਰਦਾਨ ਕੀਤੇ ਬਿਨਾਂ ਕਦੇ ਵੀ ਕੰਮ ਸ਼ੁਰੂ ਨਾ ਕਰੋ — ਇਹ ਤੁਹਾਡੇ ਕੰਮ ਦੇ ਰਿਕਾਰਡ ਅਤੇ ਬੀਮਾ ਸੁਰੱਖਿਆ ਦੀ ਗਰੰਟੀ ਦਿੰਦਾ ਹੈ।",
  "workerMandatory1Title": "ਕੰਮ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਹਮੇਸ਼ਾ OTP ਪ੍ਰਾਪਤ ਕਰੋ:",
  "workerMandatory2Desc": "ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਤੁਹਾਡਾ ਮੁੱਖ ਕਿੱਤਾ ਅਤੇ ਤਜਰਬੇ ਦੇ ਸਹੀ ਸਾਲ/ਮਹੀਨੇ ਅੱਪ-ਟੂ-ਡੇਟ ਹਨ ਤਾਂ ਜੋ AI ਡਿਸਪੈਚਰ ਤੁਹਾਨੂੰ ਮੇਲ ਖਾਂਦੇ ਕੰਮ ਭੇਜ ਸਕੇ।",
  "workerMandatory2Title": "ਹੁਨਰ ਦੇ ਵੇਰਵੇ ਸਹੀ ਰੱਖੋ:",
  "workerMandatory3Desc": "ਕਾਮਾ",
  "workerMandatory3Title": "ਅਕੈਡਮੀ ਦੇ ਪਾਠ ਪੂਰੇ ਕਰੋ:",
  "workerMandatory4Desc": "ਜੇਕਰ ਕੋਈ ਗਾਹਕ ਭੁਗਤਾਨ ਕਰਨ ਤੋਂ ਇਨਕਾਰ ਕਰਦਾ ਹੈ ਜਾਂ ਅਸੁਰੱਖਿਅਤ ਮਾਹੌਲ ਪੈਦਾ ਕਰਦਾ ਹੈ, ਤਾਂ ਫੋਟੋਆਂ ਜਾਂ ਸੁਨੇਹੇ ਦੀਆਂ ਰਸੀਦਾਂ ਨਾਲ ਤੁਰੰਤ ਸ਼ਿਕਾਇਤ ਟੈਬ ਅਧੀਨ ਸ਼ਿਕਾਇਤ ਦਰਜ ਕਰੋ।",
  "workerMandatory4Title": "ਤੁਰੰਤ ਵਿਵਾਦ ਦਰਜ ਕਰੋ:",
  "workerManualDesc": "ਸਹਿਕਾਰ ਕਨੈਕਟ ਵਰਕਰ ਪੋਰਟਲ ਦੀ ਹਰੇਕ ਵਿਸ਼ੇਸ਼ਤਾ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ ਸਰਲ ਕਦਮ-ਦਰ-ਕਦਮ ਨਿਰਦੇਸ਼।",
  "workerManualTag": "ਵਰਕਰ ਮੈਨੂਅਲ ਅਤੇ ਗਾਈਡ",
