  "workerNeedMoreHelpDesc": "ਆਪਣੇ ਸਥਾਨਕ ਜ਼ੋਨਲ ਸਹਿਕਾਰੀ ਫੈਡਰੇਸ਼ਨ ਦਫ਼ਤਰ ਨਾਲ ਸੰਪਰਕ ਕਰੋ ਜਾਂ ਸਾਡੀ ਸਮਰਪਿਤ ਸਹਾਇਤਾ ਹੈਲਪਲਾਈਨ 'ਤੇ ਪਹੁੰਚ ਕਰੋ।",
  "workerNetPayout": "ਕਾਮੇ ਦਾ ਸ਼ੁੱਧ ਭੁਗਤਾਨ",
  "workerPortal": "ਸਹਿਕਾਰੀ ਵਰਕਰ ਪੋਰਟਲ",
  "workerProfilePendingVerifyDesc": "ਤੁਹਾਡੇ ਹੁਨਰ ਦੇ ਵੇਰਵੇ ਸਹਿਕਾਰੀ ਪ੍ਰਸ਼ਾਸਨ ਵਿਭਾਗ ਨੂੰ ਜਮ੍ਹਾਂ ਕਰ ਦਿੱਤੇ ਗਏ ਹਨ। ਪੁਸ਼ਟੀ ਹੋਣ ਤੱਕ ਤੁਹਾਡੀ ਸਥਿਤੀ 'ਜਾਂਚ ਚੱਲ ਰਹੀ ਹੈ' ਦਿਖਾਈ ਦੇਵੇਗੀ। ਮਨਜ਼ੂਰੀ ਤੋਂ ਬਾਅਦ ਇਹ ਆਪਣੇ ਆਪ 'ਪ੍ਰਮਾਣਿਤ' ਹੋ ਜਾਵੇਗੀ।",
